-- Study assumptions: inventory has one row per product and a nonnegative quantity.
BEGIN;
UPDATE inventory
SET quantity = quantity - 1
WHERE product_id = 42 AND quantity > 0
RETURNING product_id, quantity;
-- Only if one row was returned, insert the order in this transaction.
COMMIT;

-- Study assumptions: both account IDs exist, amount is positive, and business checks pass.
BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;
-- On a failed check or statement, issue ROLLBACK instead.

-- Study assumptions: coupons.code is unique; one successful redemption per code.
BEGIN;
SELECT code FROM coupons
WHERE code = 'ABC123' AND redeemed = false
FOR UPDATE;
-- Only if the SELECT returned a row:
UPDATE coupons SET redeemed = true WHERE code = 'ABC123';
-- Insert the redemption record here in the same transaction.
COMMIT;
